L({ id: "b1-ecrire", lvl: "B1", tr: "style", cat: "registre", t: "Écrire un message, une lettre", en: "Formulas for informal and formal writing",
  rule: { h: "Match the opening, the closing and tu/vous to the person you write to.",
    pts: ["<b>Friend</b>: <i>Salut Claire, / Chère Claire,</i> … <i>Bisous, / À bientôt, / Je t'embrasse</i>; tutoiement.", "<b>Formal</b>: <i>Madame, / Monsieur, / Madame, Monsieur,</i> … <i>Je vous prie d'agréer, Madame, Monsieur, l'expression de mes salutations distinguées.</i>; vouvoiement.", "Semi-formal e-mail: <i>Bonjour Madame Martin,</i> … <i>Cordialement, / Bien cordialement,</i>.", "Structure for DELF B1: greeting, why you write, your point of view with reasons and examples, a conclusion, closing formula.", "Useful openings: <i>Je vous écris pour…, Suite à votre annonce…, Je me permets de vous contacter car…</i>"],
    ex: [["Chère Sophie, merci beaucoup pour ton invitation !", "Dear Sophie, thank you very much for your invitation!"], ["Madame, Monsieur, je vous écris au sujet de votre annonce.", "Dear Sir or Madam, I am writing about your advertisement."], ["Je reste à votre disposition pour tout renseignement complémentaire.", "I remain at your disposal for any further information."], ["Dans l'attente de votre réponse, je vous prie d'agréer mes salutations distinguées.", "Looking forward to your reply, yours faithfully."]],
    warn: "Never mix tu and vous in one letter, and never write <i>Cher Madame</i>: in French you write simply <i>Madame,</i>.",
    vn: "Giống thư tiếng Việt: <b>viết cho bạn</b> thì thân mật (tu, Bisous), <b>viết cho cơ quan</b> thì trang trọng (vous, công thức kết thúc dài). Trong DELF, sai giọng văn (registre) bị trừ điểm." },
  cards: [["Je vous écris pour…", "I am writing to…", "Je vous écris pour demander des informations.", "I am writing to ask for information."], ["Suite à…", "Following…", "Suite à notre conversation, je vous envoie le document.", "Following our conversation, I'm sending you the document."], ["au sujet de", "about, regarding", "Je vous contacte au sujet de la facture.", "I'm contacting you about the invoice."], ["Cordialement", "Kind regards", "Cordialement, Lan Anh Pham", "Kind regards, Lan Anh Pham"], ["Je vous prie d'agréer…", "Yours faithfully (formal)", "Je vous prie d'agréer, Madame, l'expression de mes salutations distinguées.", "Yours faithfully."], ["rester à votre disposition", "to remain at your disposal", "Je reste à votre disposition.", "I remain at your disposal."], ["Je t'embrasse", "Love, hugs (to a friend)", "À très vite, je t'embrasse !", "Speak soon, love!"], ["Dans l'attente de votre réponse", "Looking forward to your reply", "Dans l'attente de votre réponse, je vous remercie.", "Looking forward to your reply, thank you."]],
  sent: [["Salut Thomas, ça fait longtemps ! Comment vas-tu ?", "Hi Thomas, it's been ages! How are you?"], ["Madame, Monsieur, je souhaiterais m'inscrire au cours du soir.", "Dear Sir or Madam, I would like to enrol in the evening class."], ["Je vous écris pour signaler un problème de chauffage.", "I am writing to report a heating problem."], ["Pourriez-vous m'indiquer les horaires d'ouverture ?", "Could you tell me the opening hours?"], ["Je vous remercie par avance de votre réponse.", "Thank you in advance for your reply."], ["Merci encore pour ce week-end, c'était super !", "Thanks again for this weekend, it was great!"], ["Suite à votre annonce, je suis intéressée par le poste.", "Following your advertisement, I am interested in the position."], ["Je reste à votre disposition pour un entretien.", "I am available for an interview."], ["Bien cordialement, Lan Anh", "Best regards, Lan Anh"], ["Donne-moi de tes nouvelles, je t'embrasse.", "Let me know how you are, love."]],
  nat: [["Madame, je vous écris au sujet de ma commande.", "Cher Madame, je t'écris au sujet de ma commande.", "Formal letter: Madame, and vous."], ["Cordialement, Lan Anh Pham", "Bisous, Lan Anh Pham (to the bank)", "To an institution: Cordialement."], ["Salut Claire, merci pour ton message !", "Salut Claire, merci pour votre message !", "A friend: tu, ton."], ["Je vous prie d'agréer mes salutations distinguées.", "Je vous prie d'agréer mes bisous distingués.", "The formal closing formula is fixed."]],
  mcq: [["Writing to your landlord, which opening fits?", "Madame, je vous écris au sujet du loyer.", ["Salut, je t'écris pour le loyer.", "Cher Madame, je te contacte.", "Coucou ! Le loyer…"], "Formal: Madame + vous."], ["Closing an e-mail to a colleague you don't know well:", "Cordialement", ["Bisous", "Je t'embrasse", "Salut"], "Neutral professional closing."], ["Which request is polite and formal?", "Pourriez-vous me confirmer la date ?", ["Confirme-moi la date.", "Tu peux confirmer ?", "Confirmez date."], "Conditional + vous."], ["Starting a reply to a job advert:", "Suite à votre annonce parue sur votre site…", ["Salut, j'ai vu ton annonce…", "Je veux le travail.", "Coucou l'équipe !"], "Formal opening."]],
  gap: [["Je vous écris ___ sujet de votre annonce.", "au", "", "I'm writing about your advertisement.", ["à", "du", "sur"]], ["___ à notre conversation, voici le document.", "Suite", "", "Following our conversation, here is the document.", ["Après", "Depuis", "Grâce"]], ["Je reste à votre ___ pour toute question.", "disposition", "", "I remain at your disposal for any question.", ["disponible", "service de", "attente"]], ["Dans l'___ de votre réponse, je vous remercie.", "attente", "", "Looking forward to your reply, thank you.", ["espoir", "attendre", "idée"]], ["Je vous ___ par avance de votre aide.", "remercie", "", "Thank you in advance for your help.", ["merci", "remerciez", "remercier"]], ["Merci pour ton invitation, je t'___ !", "embrasse", "", "Thanks for your invitation, love!", ["embrasser", "embrassez", "salue"]]],
  fix: [["Cher Madame Dupont, je vous écris…", "Cher Madame Dupont", "Madame", "In French formal letters: Madame, (no Cher, no surname).", ["Chère Dupont", "Salut Madame"]], ["Monsieur, je t'écris pour réserver une chambre.", "je t'écris", "je vous écris", "Formal letter: vous throughout.", ["je lui écris", "j'écris toi"]], ["Monsieur, je vous écris pour réserver une chambre. Bisous, Lan Anh", "Bisous", "Cordialement", "Don't mix registers in one letter.", ["Je t'embrasse", "Salut"]]],
  xf: [["Make it formal.", "Tu peux m'envoyer le programme ?", "Pourriez-vous m'envoyer le programme ?|Pourriez-vous m'envoyer le programme, s'il vous plaît ?"], ["Make it formal.", "Je t'écris pour le stage.", "Je vous écris au sujet du stage.|Je vous écris pour le stage."]],
  chat: [["(Your new manager, by e-mail) Pourriez-vous me confirmer votre disponibilité jeudi ?", "Bonjour Madame Leroy, je vous confirme que je suis disponible jeudi. Cordialement, Lan Anh", ["Salut ! Oui, jeudi ça marche. Bisous", "Ok jeudi."], "A manager you don't know well: formal or semi-formal register."], ["(A friend) Tu viens à mon anniversaire samedi ?", "Avec plaisir ! Merci pour l'invitation, à samedi !", ["Je vous prie d'agréer mes salutations distinguées.", "Madame, je viendrai."], "A friend: informal register."]]
});
